SELECT pv.product_variant_id, p.product_id, p.product_name, pv.product_code, c.color_name, pv.unit_price, pv.stock_quantity, p.assembly_available, p.assembly_fee FROM product_variants pv JOIN products p ON p.product_id = pv.product_id JOIN colors c ON c.color_id = pv.color_id WHERE pv.product_variant_id IN
#{id}
AND p.sale_start_at <= #{now} AND (p.sale_end_at IS NULL OR p.sale_end_at > #{now})
